/**
 * دارایی واقعی → ملک (Real Estate module)
 *
 * These tests lock down the non-negotiable rules of the real estate module:
 *
 *   1. City / neighborhood / property type come ONLY from active master data —
 *      free text is rejected (no name/symbol/city/area/type typed by users).
 *   2. Asset name AND symbol are generated by the system; symbol is unique
 *      (RE-AHZ-KPE-APT-0001) and immutable.
 *   3. The user enters PERSIAN dates; the system stores Gregorian/ISO and the
 *      Persian display copy (never two independent contradicting dates).
 *   4. Purchase USD = purchase Toman ÷ FX rate OF THE ACQUISITION DATE
 *      (never today's rate); Current USD = current Toman ÷ FX rate OF THE
 *      VALUATION DATE. Both rates are frozen and auditable.
 *   5. A property bought BEFORE the system existed is a PRIOR-PERIOD
 *      ACQUISITION: the ledger entry is dated at the REAL acquisition date,
 *      credits Opening Equity, and NEVER creates a cash outflow at the
 *      system-entry date.
 *   6. Historical transactions are immutable: a revaluation updates only the
 *      current value (+ prices row), never the ledger entry.
 *   7. The current value automatically enters the aggregates (real-asset
 *      totals AND net worth), in USD at the valuation-date rate.
 *   8. Master data is extensible: admins can add/rename/deactivate
 *      cities, neighborhoods and property types; inactive entries are not
 *      selectable by normal users.
 */
import assert from "node:assert/strict";
import { test } from "node:test";
