import { db } from "../src/db";
import { createSchemaIfNotExists } from "../src/db/init-schema";
import {
  accounts,
  assets,
  exchangeRates,
  journalEntries,
  postings,
  prices,
  realEstateProperties,
  cities,
  neighborhoods,
  propertyTypes,
} from "../src/db/schema";
import {
  createRealEstateAsset,
  listRealEstateAssets,
  previewRealEstateIdentity,
  recordRealEstateValuation,
  computePerformance,
  buildAssetName,
  buildSymbol,
} from "../src/features/rwa/realEstate/service";
import {
  createNeighborhood,
  listNeighborhoods,
  listPropertyTypes,
  setNeighborhoodActive,
  seedRealEstateMasterData,
} from "../src/features/rwa/realEstate/masterData";
import { getNetWorth } from "../src/features/ledger/queries";
import { jalaliToIso } from "../src/lib/format";
import { D } from "../src/domain/decimal";

/* 1404/05/20 → 2025-08-11 ; 1405/05/20 → 2026-08-11 (today in the sandbox) */
const ACQUISITION = jalaliToIso(1404, 5, 20);
const VALUATION = jalaliToIso(1405, 5, 20);
const PURCHASE_TOMAN = "4500000000";
const CURRENT_TOMAN = "7000000000";

async function reset() {
  await createSchemaIfNotExists();
  await db.delete(realEstateProperties);
  await db.delete(prices);
  await db.delete(postings);
  await db.delete(journalEntries);
  await db.delete(exchangeRates);
  // Re-seed master data from scratch (fresh in-memory DB per test file).
  await db.delete(neighborhoods);
  await db.delete(propertyTypes);
  await db.delete(cities);
  await seedRealEstateMasterData();
}

async function setFxRate(date: string, rate: string) {
  await db
    .insert(exchangeRates)
    .values({ baseCurrency: "USD", quoteCurrency: "IRT", effectiveDate: date, rate, source: "test" })
    .onConflictDoNothing();
}

async function pickAhvazKianparsEastApartment() {
  const cityRows = await db.select().from(cities).where(eq(cities.code, "AHZ"));
  assert.ok(cityRows[0], "Ahvaz city must be seeded");
  const hoodRows = await db.select().from(neighborhoods).where(eq(neighborhoods.code, "KPE"));
  assert.ok(hoodRows[0], "Kianpars East must be seeded");
  const typeRows = await db.select().from(propertyTypes).where(eq(propertyTypes.code, "APT"));
  assert.ok(typeRows[0], "Apartment type must be seeded");
  return { cityId: cityRows[0]!.id, neighborhoodId: hoodRows[0]!.id, propertyTypeId: typeRows[0]!.id };
}

async function ledgerEntryOf(propertyId: string) {
  const [row] = await db
    .select({ entryId: realEstateProperties.ledgerEntryId })
    .from(realEstateProperties)
    .where(eq(realEstateProperties.id, propertyId))
    .limit(1);
  return row?.entryId ?? null;
}

/* ─────────────────────────── master data ─────────────────────────── */

test("master data seeds Ahvaz, its 16 neighborhoods and 12 property types", async () => {
  await reset();
  const cityRows = await db.select().from(cities);
  assert.equal(cityRows.length, 1);
  assert.equal(cityRows[0]!.code, "AHZ");
  assert.equal(cityRows[0]!.nameFa, "اهواز");

  const hoods = await listNeighborhoods(cityRows[0]!.id);
  assert.equal(hoods.length, 16, "all 16 Ahvaz neighborhoods must be seeded");
  const hoodCodes = hoods.map((h) => h.code);
  for (const code of ["GOL", "SAD", "FAR", "BAG", "AMA", "KUR", "KNO", "KPE", "KPW", "SDU", "ZKA", "KAE", "KAW", "PAD", "ARS", "MHR"]) {
    assert.ok(hoodCodes.includes(code), `neighborhood ${code} missing`);
  }

  const types = await listPropertyTypes();
  assert.equal(types.length, 12, "all 12 property types must be seeded");
  const typeCodes = types.map((t) => t.code);
  for (const code of ["APT", "HOU", "LND", "SHO", "OFF", "VIL", "GAR", "ADM", "IND", "WAR", "PRK", "OTH"]) {
    assert.ok(typeCodes.includes(code), `property type ${code} missing`);
  }
});

test("master data is extensible: add + deactivate + rename a neighborhood", async () => {
  await reset();
  const cityRows = await db.select().from(cities).where(eq(cities.code, "AHZ"));
  const hood = await createNeighborhood({ cityId: cityRows[0]!.id, nameFa: "محله آزمایشی", nameEn: "Test Hood", code: "TST" });
  assert.ok(hood.id);

  // Deactivated → hidden from normal users, still present for admins.
  await setNeighborhoodActive(hood.id, false);
  const active = await listNeighborhoods(cityRows[0]!.id);
  assert.ok(!active.some((h) => h.id === hood.id), "inactive neighborhood must not be listed for users");
  const all = await listNeighborhoods(cityRows[0]!.id, true);
  assert.ok(all.some((h) => h.id === hood.id), "inactive neighborhood must still exist for admins");
});

/* ─────────────────────── name & symbol ─────────────────────── */

test("name and symbol are generated: RE-AHZ-KPE-APT-0001 pattern, sequence for duplicates", async () => {
  await reset();
  const ids = await pickAhvazKianparsEastApartment();
  await setFxRate(ACQUISITION, "100000");
  await setFxRate(VALUATION, "100000");

  const first = await createRealEstateAsset({
    cityId: ids.cityId,
    neighborhoodId: ids.neighborhoodId,
    propertyTypeId: ids.propertyTypeId,
    acquisitionDate: ACQUISITION,
    acquisitionDatePersian: "1404/05/20",
    valuationDate: VALUATION,
    valuationDatePersian: "1405/05/20",
    purchasePriceToman: PURCHASE_TOMAN,
    currentValueToman: CURRENT_TOMAN,
  });
  assert.equal(first.symbol, "RE-AHZ-KPE-APT-0001");
  assert.equal(first.assetName, "آپارتمان — اهواز — کیانپارس شرقی");

  // Same area + same type → sequential suffix and next symbol.
  const second = await createRealEstateAsset({
    cityId: ids.cityId,
    neighborhoodId: ids.neighborhoodId,
    propertyTypeId: ids.propertyTypeId,
    acquisitionDate: ACQUISITION,
    acquisitionDatePersian: "1404/05/20",
    valuationDate: VALUATION,
    valuationDatePersian: "1405/05/20",
    purchasePriceToman: PURCHASE_TOMAN,
    currentValueToman: CURRENT_TOMAN,
  });
  assert.equal(second.symbol, "RE-AHZ-KPE-APT-0002");
  assert.equal(second.assetName, "آپارتمان — اهواز — کیانپارس شرقی — 002");

  // Symbols are unique in the assets table (DB unique constraint).
  const symbols = await db.select({ s: assets.symbol }).from(assets).where(sql`symbol like 'RE-%'`);
  assert.equal(new Set(symbols.map((r) => r.s)).size, symbols.length, "symbols must be unique");

  // Preview returns the same generated values.
  const preview = await previewRealEstateIdentity(ids.cityId, ids.neighborhoodId, ids.propertyTypeId);
  assert.equal(preview?.symbol, "RE-AHZ-KPE-APT-0003");
  assert.equal(preview?.assetName, "آپارتمان — اهواز — کیانپارس شرقی — 003");
});

