/* ─────────────────────── historical FX ─────────────────────── */

test("purchase USD uses the ACQUISITION-date rate; current USD uses the VALUATION-date rate", async () => {
  await reset();
  const ids = await pickAhvazKianparsEastApartment();
  await setFxRate(ACQUISITION, "90000"); // 1404/05/20
  await setFxRate(VALUATION, "150000"); // 1405/05/20
  // A "today" rate that must NEVER be used:
  await setFxRate("2026-08-11", "999999");

  const result = await createRealEstateAsset({
    cityId: ids.cityId,
    neighborhoodId: ids.neighborhoodId,
    propertyTypeId: ids.propertyTypeId,
    acquisitionDate: ACQUISITION,
    acquisitionDatePersian: "1404/05/20",
    valuationDate: VALUATION,
    valuationDatePersian: "1405/05/20",
    purchasePriceToman: PURCHASE_TOMAN,
    currentValueToman: CURRENT_TOMAN,
  });

  const assetsList = await listRealEstateAssets();
  const asset = assetsList.find((a) => a.id === result.id);
  assert.ok(asset, "property must appear in the asset list");

  assert.equal(asset!.purchaseFxRate, "90000");
  assert.equal(asset!.purchaseFxRateDate, ACQUISITION);
  assert.equal(asset!.purchaseFxRateSource, "exact");
  // 4,500,000,000 ÷ 90,000 = 50,000 USD
  assert.equal(asset!.purchaseValueUsd, "50000.00");

  assert.equal(asset!.valuationFxRate, "150000");
  assert.equal(asset!.valuationFxRateDate, VALUATION);
  assert.equal(asset!.valuationFxRateSource, "exact");
  // 7,000,000,000 ÷ 150,000 = 46,666.67 USD
  assert.equal(asset!.currentValueUsd, "46666.67");

  // Neither amount was computed with today's 999,999 rate.
  // (If today's rate had been used, 7B ÷ 999,999 ≈ 7,000 USD — nowhere near 46,666.)
  assert.ok(!asset!.purchaseValueUsd?.startsWith("4500"));
  assert.ok(Number(asset!.currentValueUsd) > 10000, "must not use today's rate");
});

test("rates are frozen: a later FX change never rewrites stored values", async () => {
  await reset();
  const ids = await pickAhvazKianparsEastApartment();
  await setFxRate(ACQUISITION, "80000");
  await setFxRate(VALUATION, "80000");

  const result = await createRealEstateAsset({
    cityId: ids.cityId,
    neighborhoodId: ids.neighborhoodId,
    propertyTypeId: ids.propertyTypeId,
    acquisitionDate: ACQUISITION,
    acquisitionDatePersian: "1404/05/20",
    valuationDate: VALUATION,
    valuationDatePersian: "1405/05/20",
    purchasePriceToman: PURCHASE_TOMAN,
    currentValueToman: CURRENT_TOMAN,
  });

  // Insert a new "current" rate — the frozen values must not move.
  await setFxRate("2026-08-11", "500000");
  const after = await listRealEstateAssets();
  const asset = after.find((a) => a.id === result.id)!;
  assert.equal(asset.purchaseValueUsd, "56250.00"); // 4.5B ÷ 80k
  assert.equal(asset.currentValueUsd, "87500.00"); // 7B ÷ 80k
  assert.equal(asset.purchaseFxRate, "80000");
});

