/* ─────────────────────── ledger integration ─────────────────────── */

test("prior-period acquisition posts an OPENING entry dated at the acquisition date — no cash outflow today", async () => {
  await reset();
  const ids = await pickAhvazKianparsEastApartment();
  await setFxRate(ACQUISITION, "90000");
  await setFxRate(VALUATION, "90000");

  const result = await createRealEstateAsset({
    cityId: ids.cityId,
    neighborhoodId: ids.neighborhoodId,
    propertyTypeId: ids.propertyTypeId,
    acquisitionDate: ACQUISITION,
    acquisitionDatePersian: "1404/05/20",
    valuationDate: VALUATION,
    valuationDatePersian: "1405/05/20",
    purchasePriceToman: PURCHASE_TOMAN,
    currentValueToman: CURRENT_TOMAN,
  });

  const entryId = await ledgerEntryOf(result.id);
  assert.ok(entryId, "asset ↔ ledger link must be stored");

  const [entry] = await db.select().from(journalEntries).where(eq(journalEntries.id, entryId!));
  assert.ok(entry, "ledger entry must exist");
  assert.equal(entry.entryDate, ACQUISITION, "entry must be dated at the REAL acquisition date");
  assert.equal(entry.type, "opening");
  assert.equal(entry.status, "posted");
  assert.match(entry.description, new RegExp(result.symbol));

  const lines = await db.select().from(postings).where(eq(postings.entryId, entryId!));
  assert.equal(lines.length, 2, "double-entry: exactly two postings");

  const accIds = lines.map((l) => l.accountId);
  const [assetAccount] = await db.select().from(accounts).where(eq(accounts.code, "1600"));
  const [equityAccount] = await db.select().from(accounts).where(eq(accounts.code, "3015"));
  assert.ok(assetAccount && equityAccount, "real-estate asset + opening equity accounts must exist");
  assert.ok(accIds.includes(assetAccount!.id), "Debit leg on the real-estate asset account");
  assert.ok(accIds.includes(equityAccount!.id), "Credit leg on opening equity — not cash");

  // Balanced: Σ base_value = 0 ; the debit leg carries the purchase USD value.
  const sumBase = lines.reduce((s, l) => s.add(D(l.baseValue)), D("0"));
  assert.equal(sumBase.toFixed(6), "0.000000", "entry must be balanced");
  const debit = lines.find((l) => D(l.baseValue).gt(0))!;
  assert.equal(D(debit.baseValue).toFixed(2), "50000.00", "debit = purchase USD at acquisition-date rate");

  // No cash outflow anywhere near the system entry date.
  const cashAccounts = await db
    .select({ id: accounts.id })
    .from(accounts)
    .where(sql`code in ('1010','1020','1030')`);
  const cashIds = cashAccounts.map((c) => c.id);
  assert.ok(!lines.some((l) => cashIds.includes(l.accountId)), "cash accounts must not be touched");
  const todayEntries = await db.select().from(journalEntries).where(sql`entry_date = current_date`);
  assert.equal(todayEntries.length, 0, "no entry may be dated at the system-entry date");
});

test("similar properties in one area get unique symbols and their own ledger entries", async () => {
  await reset();
  const ids = await pickAhvazKianparsEastApartment();
  await setFxRate(ACQUISITION, "100000");
  await setFxRate(VALUATION, "100000");
  const input = {
    cityId: ids.cityId,
    neighborhoodId: ids.neighborhoodId,
    propertyTypeId: ids.propertyTypeId,
    acquisitionDate: ACQUISITION,
    acquisitionDatePersian: "1404/05/20",
    valuationDate: VALUATION,
    valuationDatePersian: "1405/05/20",
    purchasePriceToman: PURCHASE_TOMAN,
    currentValueToman: CURRENT_TOMAN,
  };
  const a = await createRealEstateAsset(input);
  const b = await createRealEstateAsset(input);
  assert.notEqual(a.symbol, b.symbol, "each property must get a unique symbol");

  const entries = await db.select().from(journalEntries);
  assert.equal(entries.length, 2, "each property posts its own ledger entry");
  for (const e of entries) {
    assert.equal(e.type, "opening");
    assert.equal(e.entryDate, ACQUISITION);
    const lines = await db.select().from(postings).where(eq(postings.entryId, e.id));
    assert.equal(lines.length, 2);
    const sum = lines.reduce((s, l) => s.add(D(l.baseValue)), D("0"));
    assert.equal(sum.toFixed(6), "0.000000", "each entry balanced");
  }
});

/* ─────────────────────── revaluation & immutability ─────────────────────── */

test("a new valuation updates only the current value — the ledger entry stays untouched", async () => {
  await reset();
  const ids = await pickAhvazKianparsEastApartment();
  await setFxRate(ACQUISITION, "100000");
  await setFxRate(VALUATION, "100000");

  const result = await createRealEstateAsset({
    cityId: ids.cityId,
    neighborhoodId: ids.neighborhoodId,
    propertyTypeId: ids.propertyTypeId,
    acquisitionDate: ACQUISITION,
    acquisitionDatePersian: "1404/05/20",
    valuationDate: VALUATION,
    valuationDatePersian: "1405/05/20",
    purchasePriceToman: PURCHASE_TOMAN,
    currentValueToman: CURRENT_TOMAN,
  });
  const entryId = await ledgerEntryOf(result.id);
  const entryBefore = await db.select().from(journalEntries).where(eq(journalEntries.id, entryId!));
  const postingsBefore = await db.select().from(postings).where(eq(postings.entryId, entryId!));
  const [priceBefore] = await db.select().from(prices).where(eq(prices.assetId, result.assetId));

  const NEW_DATE = jalaliToIso(1405, 8, 1); // 2026-10-23
  await setFxRate(NEW_DATE, "120000");
  const reval = await recordRealEstateValuation({
    propertyId: result.id,
    valuationDate: NEW_DATE,
    valuationDatePersian: "1405/08/01",
    currentValueToman: "8400000000",
  });

  assert.equal(reval.currentValueToman, "8400000000");
  assert.equal(reval.currentValueUsd, "70000.00"); // 8.4B ÷ 120k
  assert.equal(reval.valuationFxRate, "120000");

  // Ledger untouched — immutable.
  const entryAfter = await db.select().from(journalEntries).where(eq(journalEntries.id, entryId!));
  const postingsAfter = await db.select().from(postings).where(eq(postings.entryId, entryId!));
  assert.deepEqual(entryAfter, entryBefore, "ledger entry must be immutable");
  assert.deepEqual(postingsAfter, postingsBefore, "postings must be immutable");

  // A NEW price row was appended (valuation-date rate), old one preserved.
  const priceRows = await db.select().from(prices).where(eq(prices.assetId, result.assetId)).orderBy(prices.asOf);
  assert.equal(priceRows.length, 2);
  assert.equal(priceRows[0]!.asOf, VALUATION, "first price row (original valuation) preserved");
  assert.equal(priceRows[1]!.asOf, NEW_DATE, "second price row dated at the new valuation date");
  assert.equal(D(priceRows[1]!.priceBase).toFixed(2), "70000.00"); // 8.4B ÷ 120k
  assert.ok(priceBefore, "first price row still exists");
});

/* ─────────────────────── aggregates / net worth ─────────────────────── */

test("current value enters the real-asset totals AND total net worth (USD at valuation-date rate)", async () => {
  await reset();
  const ids = await pickAhvazKianparsEastApartment();
  await setFxRate(ACQUISITION, "100000");
  await setFxRate(VALUATION, "100000");

  const result = await createRealEstateAsset({
    cityId: ids.cityId,
    neighborhoodId: ids.neighborhoodId,
    propertyTypeId: ids.propertyTypeId,
    acquisitionDate: ACQUISITION,
    acquisitionDatePersian: "1404/05/20",
    valuationDate: VALUATION,
    valuationDatePersian: "1405/05/20",
    purchasePriceToman: PURCHASE_TOMAN,
    currentValueToman: CURRENT_TOMAN,
  });

  const { getRealEstatePortfolioSummary } = await import("../src/features/rwa/realEstate/service");
  const summary = await getRealEstatePortfolioSummary();
  assert.equal(summary.count, 1);
  assert.equal(summary.totalCurrentToman, CURRENT_TOMAN);
  assert.equal(summary.totalCurrentUsd, "70000.00"); // 7B ÷ 100k
  assert.equal(summary.totalPurchaseToman, PURCHASE_TOMAN);
  assert.equal(summary.totalPurchaseUsd, "45000.00");
  assert.equal(summary.totalGainToman, "2500000000");
  assert.equal(summary.totalGainUsd, "25000.00");

  // Net worth (from the ledger + prices layer) includes the property at its
  // CURRENT value: qty 1 × latest price (current USD).
  const nw = await getNetWorth();
  const propHolding = nw.byClass.find((c) => c.className === "دارایی واقعی");
  assert.ok(propHolding, "real estate must appear in net-worth by class");
  assert.equal(Number(propHolding!.value).toFixed(2), "70000.00", "net worth must use the CURRENT valuation, not purchase cost");
  assert.equal(Number(nw.totalAssets).toFixed(2), "70000.00");
});

